\label{thm:dichotomy}
Let $X$ be a real L\'evy process of infinite variation. Exactly one
of the following holds:
\begin{enumerate}[leftmargin=2em, label=\textup{(\alph*)}]
\item $J_X(I)<\infty$ for every bounded interval $I$;
\item $J_X(I)=\infty$ for every proper interval $I$.
\end{enumerate}
Equivalently, $X$ is either abrupt or strongly eroded.

\label{thm:cantor-exceptional-slopes}
There exists an abrupt pure-jump L\'evy process of infinite variation such that
\[
E=\{r\in\mathbb{R}:\mathfrak{s}_1(r)=\infty\}
\]
is a compact perfect set of Lebesgue measure zero. In particular, $E$ is uncountable but $\mathfrak{s}_1\in L^1_\mathrm{loc}(\mathbb{R})$.

\label{prop:gen-Gaussian}
Let $X$ be a real L\'evy process with zero Gaussian coefficient $\sigma=0$, L\'evy measure $\nu$, and drift $\gamma$ in the truncation convention $x\1_{\{|x|<1\}}$. Suppose that there are $r_n\downarrow0$ and $t_n\downarrow0$ such that
\begin{equation}\label{gen:cutoff-conditions}
 \frac{r_n}{t_n}\to0,\quad
 \frac{V(r_n)}{t_n}\to v\in(0,\infty),\quad 
 t_n\overline{\nu}(r_n)\to0,
\end{equation}
and $ d(r_n)\to m\in\mathbb{R}$. Then, for every fixed $s>0$,
\begin{equation}
\label{gen:Gaussian-limit}
 \frac{X_{st_n}}{st_n}\overset{\mathrm{d}}{\to}\mathcal{N}(m,v/s),
 \quad\text{as}\enskip
 n\to\infty.
\end{equation}
Moreover, $X$ has infinite variation, is strongly eroded, and $\mathfrak{s}_1\equiv\infty$.

\label{cor:orey}
Let $\alpha\in(1,2)$, $c>0$, and let $\eta$ be an integer satisfying $\eta>2/(2-\alpha)$. The symmetric L\'evy process $X$ with zero Gaussian coefficient, zero drift, and L\'evy measure $\nu$, where
\begin{equation}
\label{eq:orey-measure}
b_n=2^{-\eta^n}
\qquad\text{and}\qquad
\nu=c\sum_{n\geqslant1}b_n^{-\alpha}
(\delta_{b_n}+\delta_{-b_n}),
\end{equation}
is strongly eroded with $\mathfrak{s}_{1}\equiv\infty$ and its indices are $\beta_-=0$ and $\beta_+=\alpha$.

\label{lem:smoothed}
Set $C_0=5$, $c_0=1/32$ and $c=1/385$. Then, for every $u>0$ and $v\in[u,2u]$, we have
\begin{align}
\label{eq:HD-derivative}
\max\{|H'(u)|,|D'(u)|\}
&\leqslant u^{-1}H(u),\\
\label{eq:dyadic-HD}
\tfrac{1}{2} H(u)
\leqslant H(v)\leqslant2H(u)
\quad &\text{and}\quad 
|D(v)-D(u)| \leqslant 2(\log 2)H(u),\\
\label{eq:smoothed-approximation}
\sup_{|z|\leqslant1}|\psi(uz)-iuzD(u)|
&\leqslant C_0uH(u),\\
\min\bigg\{\int_{-1}^1 Q(uz)\mathrm{d} z,
\int_1^2 Q(uz)\mathrm{d} z\bigg\}
&\geqslant c_0uH(u)\qquad\text{and}
\label{eq:smoothed-average}\\
cu\bigl(H(u)+|D(u)|\bigr)
\leqslant P(u)
&\coloneqq\sup_{0\leqslant v\leqslant u}|\psi(v)|
\leqslant u\bigl(|D(u)|+C_0H(u)\big).
\label{eq:P-comparison}
\end{align}
Moreover, the process with characteristic exponent as in~\eqref{eq:compact-exponent} has infinite variation if and only if
\begin{equation}\label{eq:variation-H}
 \int_1^\infty H(u)\frac{\mathrm{d} u}{u}=\infty.
\end{equation}

\label{lem:energy-escape}
If $X$ has infinite variation and
\begin{equation}\label{eq:finite-energy}
 \int_1^\infty\frac{H(u)}{1+H(u)^2+D(u)^2}
                      \frac{\mathrm{d} u}{u}<\infty,
\end{equation}
then $H(u)+|D(u)|\to\infty$ and $P(u)/u\to\infty$ as $u \to \infty$.

For $u\geqslant1$ and $v\in[u,2u]$, applying~\eqref{eq:smoothed-approximation} yields $|\psi(v)-ivD(v)|\leqslant C_0vH(v)$. Since $\psi(v)-ivD(v) = -Q(v)+i(B(v)-vD(v))$, we obtain $Q(v)/v\leqslant C_0H(v)$ and $|b(v)-D(v)|\leqslant C_0H(v)$. Together with~\eqref{eq:dyadic-HD}, this yields, uniformly for
$v\in[u,2u]$,
\[
a(v)
=
\frac{1+Q(v)}v
\leqslant 1+2C_0H(u), \quad \text{and}\quad 
|b(v)|
\leqslant
|D(u)|+2(\log2)H(u)+2C_0H(u).
\]
Hence, there exists a constant $C_I<\infty$ such that, uniformly for $r\in I$ and $v\in[u,2u]$,
\begin{equation}\label{eq:dyadic-Ab-bound}
 a(v)^2+(r-b(v))^2
 \leqslant
 C_I\bigl(1+H(u)^2+D(u)^2\bigr).
\end{equation}

Since $a(v)\geqslant Q(v)/v$, it follows by~\eqref{eq:dyadic-Ab-bound}, that
\[
\Phi_I(v)
=
\int_I\frac{a(v)}
{a(v)^2+(r-b(v))^2}\,\mathrm{d} r
\geqslant
\frac{|I|\,Q(v)}
{v\,C_I\bigl(1+H(u)^2+D(u)^2\bigr)}.
\]
With the change of variables $v=uz$,~\eqref{eq:smoothed-average} gives 
\[
\int_u^{2u}Q(v)\frac{\mathrm{d} v}{v^2}
\geqslant \frac{1}{4u^2}\int_u^{2u}Q(v)\mathrm{d} v
=\frac{1}{4u}\int_1^2Q(uz)\,\mathrm{d} z
\geqslant \frac{c_0}{4}H(u),
\]
and hence
\begin{equation}
\label{eq:dyadic-Phi-lower}
\int_u^{2u}\Phi_I(v)\frac{\mathrm{d} v}{v}
\geqslant
\frac{|I|c_0H(u)}
{4C_I\bigl(1+H(u)^2+D(u)^2\bigr)}.
\end{equation}

Integrating~\eqref{eq:dyadic-Phi-lower} with respect to $u^{-1}\mathrm{d} u$ and applying Tonelli's theorem yields
\begin{equation*}
    \int_1^\infty
\frac{H(u)}{1+H(u)^2+D(u)^2}\frac{\mathrm{d} u}{u}
\leqslant
\frac{4C_I}{|I|c_0}
\int_1^\infty\int_u^{2u}
\Phi_I(v)\frac{\mathrm{d} v}{v}\frac{\mathrm{d} u}{u} \leqslant
\frac{4C_I\log2}{|I|c_0}
\int_1^\infty\Phi_I(v)\frac{\mathrm{d} v}{v}
<\infty.
\end{equation*}
Thus,~\eqref{eq:finite-energy} holds, and Lemma~\ref{lem:energy-escape} implies $P(u)/u \to \infty$ as $u \to \infty$.

Fix now $K>0$ and $\theta>0$. Since $P(u)/u\to\infty$ as $u \to \infty$, it follows that $P(\theta u)>Ku$ for all sufficiently large $u$. Hence, there exists $w$ with $|w|\leqslant\theta u$ and $|\psi(w)|>Ku$. Since $\psi(0)=0$, $|\psi(-v)|=|\psi(v)|$, and $\psi$ is continuous, the intermediate value theorem gives some $v\in(0,|w|]$ such that $|\psi(v)|=Ku$. Thus $\rho_K(u)$ is finite and $\rho_K(u)\leqslant\theta u$ for all sufficiently large $u$. Since $\theta>0$ is arbitrary, $\rho_K(u)=\mathrm{o}(u)$ as $u \to \infty$. Finally, by the definition of the first exit radius and continuity, we have $|\psi(v)|<Ku$ for all $0\leqslant v<\rho_K(u)$ and $|\psi(\rho_K(u))|=Ku$. Therefore, using $|\psi(-v)|=|\psi(v)|$, we may conclude $P(\rho_K(u))=Ku$.

\label{lem:increment}
For all $u,v \in \mathbb{R}$, we have
\begin{gather}
\label{eq:increment}
|\psi(u+v)-\psi(u)-\psi(v)|
\leqslant2\sqrt{Q(u)Q(v)}
\quad\text{and}\\
\label{eq:Q-increment}
\bigl(\sqrt{Q(v)}-\sqrt{Q(u)}\bigr)^2
\leqslant Q(u+v)
\leqslant\bigl(\sqrt{Q(v)}+\sqrt{Q(u)}\bigr)^2.
\end{gather}

\label{lem:local-average}
Suppose $P(u)/u\to\infty$. For each interval $I$ and $M>0$, there exist $c>0$ and $U<\infty$ such that, whenever $u\geqslant U$ satisfies $|\psi(u)|\leqslant Mu$, there exists some $r\in(0, 1/10]$ satisfying
\begin{equation}\label{eq:local-average}
 \frac1{ru}\int_{(1-r)u}^{(1+r)u}\Phi_I(w)\,\mathrm{d} w\geqslant c.
\end{equation}

Fix $n\geqslant 2$ and consider the family $F_n=\{J_u:\ u\in E\cap[1/n,n]\}$, where $J_u=(u-ru,u+ru)$. Since each interval $J_u$ has radius at most $u\delta/5\leqslant n\delta/5$, the radii of the intervals in $F_n$ are uniformly bounded. By the $5r$-covering theorem~\cite[Thm~2.1]{MR1333890}, there exists a finite or countable pairwise disjoint subfamily $((1-r_k)u_k,(1+r_k)u_k)_{k \in \mathcal K}$ of $F_n$ with $\mathcal K \subset \mathbb{N}$, such that
\begin{equation}
\label{eq:fivefold-cover}
E\cap[1/n,n]\subset \bigcup_{k \in \mathcal K} ((1-5r_k)u_k,(1+5r_k)u_k).
\end{equation}

Let $J_{k}=((1-r_k)u_k,(1+r_k)u_k)$. Every $w\in ((1-5r_k)u_k,(1+5r_k)u_k)$ satisfies $w\geqslant (1-\delta)u_k$, so
\begin{equation}
\label{eq:fivefold-weight}
\int_{(1-5r_k)u_k}^{(1+5r_k)u_k}\frac{\mathrm{d} w}{w}
\leqslant\frac{10}{1-\delta}r_k.
\end{equation}
Since $w\leqslant (1+r_k)u_k\leqslant (1+\delta/5)u_k$ for $w\in J_k$, the assumption $\int_{J_k} f(w)\,\mathrm{d} w\geqslant cr_ku_k$ implies that
\begin{equation}
\label{eq:J-weight}
\int_{J_k} f(w)\frac{\mathrm{d} w}{w}
\geqslant
\frac{1}{(1+\delta/5)u_k}\int_{J_k}f(w)\,\mathrm{d} w
\geqslant
\frac{cr_k}{1+\delta/5}.
\end{equation}
Combining~\eqref{eq:fivefold-weight} and~\eqref{eq:J-weight} gives $\int_{(1-5r_k)u_k}^{(1+5r_k)u_k} w^{-1}\mathrm{d} w \leqslant C\int_{J_k} f(w)w^{-1}\mathrm{d} w$ for $C\coloneqq(10+2\delta)/(c(1-\delta))$.

Using~\eqref{eq:fivefold-cover} and the pairwise disjointness of the intervals $J_{k}$, we obtain
\[
\begin{aligned}
\int_{E\cap[1/n,n]}\frac{\mathrm{d} w}{w}
\leqslant
\sum_{k \in \mathcal K}\int_{(1-5r_k)u_k}^{(1+5r_k)u_k}\frac{\mathrm{d} w}{w} 
\leqslant
C\sum_{k \in \mathcal K}\int_{J_{k}}f(u)\frac{\mathrm{d} u}{u} \leqslant
C\int_0^\infty f(u)\frac{\mathrm{d} u}{u}.
\end{aligned}
\]
The right-hand side is finite and independent of $n$. Since $E\cap[1/n,n]\uparrow E$ as $n \to \infty$, the monotone convergence theorem yields $\int_E u^{-1}\mathrm{d} u\leqslant C\int_0^\infty f(u) u^{-1}\mathrm{d} u <\infty$, which concludes the proof.

Part (i). By~\eqref{eq:Fourier-identity}, it suffices to show that, for any symmetric interval $I=(-R,R)$, we have
\begin{equation}
\label{eq:Phi-R}
\frac{\Phi_I(u)}{u}

\leqslant \min\left\{\frac{2R}{1+Q(u)}, \frac{\pi}{u}\right\} 
\leqslant \frac{2R + \pi}{1 + u + Q(u)}
\leqslant \frac{2R + \pi}{u + Q(u)}.
\end{equation}
The third inequality in~\eqref{eq:Phi-R} is trivial, while the second one follows from the first one because
\begin{equation}
\label{eq:mid-frac}
\min\bigg\{\frac{x_1}{y_1},\frac{x_2}{y_2}\bigg\}
\leqslant\frac{x_1+x_2}{y_1+y_2}
\leqslant\max\bigg\{\frac{x_1}{y_1},\frac{x_2}{y_2}\bigg\},
\quad \text{for all }
y_1,y_2>0,\text{ and }
x_1,x_2\in\mathbb{R}.
\end{equation}
It remains to establish the first inequality in~\eqref{eq:Phi-R}. Equation~\eqref{eq:Phi} gives $\Phi_I(u)\leqslant \pi$, while the other bound follows because $|I|=2R$ and the integrand defining $\Phi_I(u)$ is bounded by $1/a(u)=u/(1+Q(u))$. 

Part (ii). Let $E_\delta\coloneqq\{u\geqslant 1:|r-b(u)|<\delta\}$. We claim that, for $u\in [1,\infty)\setminus E_\delta$, we have
\begin{equation}
\label{eq:E_delta}
\frac{1+Q(u)}{(1+Q(u))^2+(ru-B(u))^2}
\leqslant \frac{1+Q(u)}{(1+Q(u))^2+\delta^2u^2}
\leqslant\frac{2}{\min\{1,\delta^2\}}\frac{1}{u+Q(u)}.
\end{equation}
The first bound follows from the definition of $E_\delta$, while the second bound follows from elementary inequalities: for $u\geqslant 0$, $y=Q(u)\geqslant 0$, we have
\[
\frac{(1+y)^2 + \delta^2 u^2}{\min\{1, \delta^2\}}
\geqslant  (1+y)^2 + u^2 
\geqslant \frac{1}{2}(1+u+y)^2 
\geqslant \frac{1}{2}(1+y)(u+y).
\]
Since the integrand of $\mathfrak{s}_1$ is bounded by $1/(1+Q)\leqslant 1$ and $\psi(-u)=\overline{\psi(u)}$,~\eqref{eq:E_delta} yields
\[
\pi\mathfrak{s}_1(r)
\leqslant 1 + \frac{2}{\min\{1,\delta^2\}}\int_{[1,\infty)\setminus E_\delta}\frac{\mathrm{d} u}{u+Q(u)} + \int_{E_\delta}\frac{\mathrm{d} u}{1+Q(u)}
\leqslant 1+\frac{2}{\min\{1,\delta^2\}}\mathfrak{z}_0
+\mathfrak{z}(E_\delta)<\infty.
\]

Part (iii). By assumption, $C\coloneqq\sup_{u\in I}|B(u)-ur|/(1+Q(u))<\infty$. For $u\in I$, the integrand in $\mathfrak{s}_1$ is bounded below by $1/[(1+C^2)(1+Q(u))]$. Thus, $\mathfrak{s}_1(r)\geqslant [\pi(1+C^2)]^{-1}\mathfrak{z}(I) = \infty$.

\label{lem:periodic}
For any $\lambda,q,c>0$ and $t\in \mathbb{R}$, we have
\begin{equation}
\label{eq:periodic-integral}
\int_t^{t+2\pi/c}\frac{\mathrm{d} u}
{q+\lambda(1-\cos(c u))}
=\frac{2\pi/c}{\sqrt{q(q+2\lambda)}}.
\end{equation}

\label{prop:abstract-Iplus}
The process $X$ is abrupt and $\mathfrak{z}_0 = \int_1^\infty (u + Q(u))^{-1}\mathrm{d} u < \infty$ whenever
\begin{equation}
\label{eq:Iplus-condition}
\sum_{n\geqslant 1} \frac{1 + \log(h_n \vee 1)}{h_n} < \infty.
\end{equation}

\label{prop:abstract-drift-resonance}
Recall that $d_n=-\sum_{k\leqslant n}\Delta_k$ for all $n \geqslant 1$, and set $d_0\coloneqq0$.
\begin{enumerate}[label=\textup{(\roman*)},leftmargin=2em]
\item For all $u>0$ and $n\geqslant1$, we have that
\begin{equation}
\label{eq:B-drift-tracking}
|B(u)-d_nu|
\leqslant
2a_n^{-1}+\frac13a_{n+1}^2u^3.
\end{equation}
\item Fix $C\geqslant1$ and $n\geqslant 1$. Suppose
\begin{equation}
\label{eq:drift-resonance-head-tail}
1+2L_{n-1}
\leqslant
C v_{n+1}a_n^{-2}
\quad\text{and}\quad
S_n\leqslant C v_{n+1}.
\end{equation}
Then, for every $u\geqslant a_n^{-1}$, it holds that 
\begin{equation}
\label{eq:Q-upper-tail}
1+Q(u)
\leqslant
\lambda_n\bigl(1-\cos(a_nu)\bigr)
+\frac{3C}{2}v_{n+1}u^2.
\end{equation}
\item Fix $C\geqslant1$, suppose 
\eqref{eq:drift-resonance-head-tail} holds for all sufficiently large $n$, and that $v_{n+1}/a_{n+1} \to \infty$, $\lambda_nv_{n+1} \to \infty$ as $n \to \infty$. Moreover, set $W_n\coloneqq 4/\sqrt{a_nv_{n+1}}$, and assume that $I_n\coloneqq[W_n,v_{n+1}^{-1}]\subset[a_n^{-1},a_{n+1}^{-1}]$ for all sufficiently large $n$. Then, for all sufficiently large $n$ and $u\in I_n$,
\begin{equation}
\label{eq:drift-resonance-BQ}
|B(u)-d_nu|
\leqslant
\frac{1}{4}v_{n+1}u^2
\leqslant
Q(u)
\quad\text{and}\quad
\mathfrak{z}(I_n)
\geqslant
\frac{\sqrt{2/C}}{3h_n}
\bigl(
-\log\bigl(v_{n+1}W_n\bigr)-2\pi
\bigr).
\end{equation}
\end{enumerate}

\label{prop:bounded-envelope}
Let $X$ be a real L\'evy process of infinite variation. Then $\mathfrak{s}_1\equiv\infty$ whenever
\begin{equation}
\label{eq:bounded-envelope} \liminf_{u\to\infty}\frac{P(u)}u<\infty.
\end{equation}

For $0<r<1$, the L\'evy--Khintchine formula gives the exact decomposition
\begin{equation}\label{gen:cutoff-decomposition}
\psi(u)
=
iud(r)
+\int_{(-r,r)}(e^{iux}-1-iux)\nu(\mathrm{d} x)
+\int_{\mathbb{R}\setminus(-r,r)}(e^{iux}-1)\nu(\mathrm{d} x).
\end{equation}
Fix $s>0$ and $\xi\in\mathbb{R}$. Applying $|e^{iz}-1-iz+z^2/2|\leqslant |z|^3/6$ to the small jumps with $r=r_n$ and $u=\xi/(st_n)$, and using $|e^{iz}-1|\leqslant2$ on the tails, we obtain
\begin{equation}
\label{gen:error-bound}
\left|
st_n\psi\left(\frac{\xi}{st_n}\right)
-i\xi d(r_n)
+\frac{\xi^2}{2s}\frac{V(r_n)}{t_n}
\right|
\leqslant
\frac{|\xi|^3}{6s^2}
\frac{r_n}{t_n}\frac{V(r_n)}{t_n}
+2st_n\overline{\nu}(r_n).
\end{equation}
By~\eqref{gen:cutoff-conditions} and $d(r_n)\to m$, the right-hand side tends to zero, so $st_n\psi(\xi/(st_n)) \to i\xi m - v\xi^2/(2s)$. L\'evy's continuity theorem yields~\eqref{gen:Gaussian-limit}. Infinite variation follows because $V(r_n)/r_n = (V(r_n)/t_n)(t_n/r_n) \to \infty$, whereas finite variation would force $V(r)/r \leqslant \int_{(-r,r)}|x|\nu(\mathrm{d} x) \to 0$ as $r\downarrow 0$.

Next, for $0\leqslant u\leqslant U_n \coloneqq 1/t_n$,~\eqref{gen:cutoff-decomposition} yields $|\psi(u)| \leqslant |d(r_n)|u + u^2 V(r_n)/2 + 2\overline{\nu}(r_n)$. Hence,
\begin{equation}\label{gen:Gaussian-envelope}
 \frac{P(U_n)}{U_n} \leqslant |d(r_n)| + \frac{V(r_n)}{2t_n} + 2t_n\overline{\nu}(r_n) \to |m| + \frac{v}{2} < \infty, \quad \text{as }n\to \infty.
\end{equation}
Since $U_n \to \infty$ as $n \to \infty$, Proposition~\ref{prop:bounded-envelope} implies that $\mathfrak{s}_1\equiv \infty$. By~\eqref{eq:occupation-equivalence}, $\int_I \mathfrak{s}_1(r)\mathrm{d} r = \infty$ for every non-empty interval $I$, so $X$ is strongly eroded.
